class Solution {
    private TreeMap<Integer, TreeMap<Integer, PriorityQueue<Integer>>> map = new TreeMap<>();

    public void dfs(TreeNode node, int col, int row){
        if(node==null) return;

        map.putIfAbsent(col, new TreeMap<>());
        map.get(col).putIfAbsent(row, new PriorityQueue<>());
        map.get(col).get(row).offer(node.data);

        dfs(node.left, col-1, row+1);
        dfs(node.right, col+1, row+1);
    }

    public List<List<Integer>> verticalTraversal(TreeNode root) {
        //your code goes here
        List<List<Integer>> result = new ArrayList<>();

        dfs(root,0,0);

        for(TreeMap<Integer, PriorityQueue<Integer>> rowmap : map.values()){
            List<Integer> column = new ArrayList<>();

            for(PriorityQueue<Integer> pq : rowmap.values()){
                while(!pq.isEmpty()){
                    column.add(pq.poll());
                }
            }
            result.add(column);
        }
        return result;
    }   
}
