public class Solution
{
    public IList<IList<int>> VerticalTraversal(TreeNode root)
    {
        // Raj Thomas 15th Jul 2026 12:17AM IST 
        // queue -> node, vertical, level
        // result -> List -> List<int> by vertical -> by level

        Queue<(TreeNode root, int vert, int level)> q = new Queue<(TreeNode root, int vert, int level)>();
        Dictionary<int, Dictionary<int, List<int>>> map = new Dictionary<int, Dictionary<int, List<int>>>();

        if(root == null) return new List<IList<int>>();

        int initialVertical = 0, initialLevel = 0;
        q.Enqueue((root, initialVertical, initialLevel));

        while(q.Count > 0) {

            int size = q.Count;
            for(int i = 0; i < size; i++) {

                (TreeNode root, int vert, int level) curr = q.Dequeue();
                TreeNode currNode = curr.Item1;
                int currVert = curr.Item2;
                int currLevel = curr.Item3;

                if(!map.ContainsKey(currVert)) {

                    List<int> items = new List<int>();
                    items.Add(currNode.val);

                    Dictionary<int, List<int>> levelMap = new Dictionary<int, List<int>>();
                    levelMap.Add(currLevel, items);

                    map.Add(currVert, levelMap);
                }
                else {

                    Dictionary<int, List<int>> levelMap = map[currVert];
                    if(!levelMap.ContainsKey(currLevel)) {
                        List<int> items = new List<int>();
                        items.Add(currNode.val);
                        levelMap.Add(currLevel, items);

                        map[currVert] = levelMap;
                    }
                    else {
                        List<int> items = levelMap[currLevel];
                        items.Add(currNode.val);
                        levelMap[currLevel] = items;

                        map[currVert] = levelMap;
                    }

                }

                // add left/right treenode to queue
                if(currNode.left != null) q.Enqueue((currNode.left, currVert - 1, currLevel + 1));
                if(currNode.right != null) q.Enqueue((currNode.right, currVert + 1, currLevel + 1));

            }
        }

        // construct result here 
        IList<IList<int>> result = new List<IList<int>>();

        foreach(var vertInfo in map.OrderBy(x => x.Key)) {

            List<int> column = new List<int>();
            foreach(var levelInfo in vertInfo.Value.OrderBy(x => x.Key)) {

                levelInfo.Value.Sort();
                column.AddRange(levelInfo.Value);
            }

            result.Add(column);
        }

        return result;

    }
}
